const { DatabaseSync } = await import('node:sqlite');
const db = new DatabaseSync(':memory:');
db.exec('CREATE TABLE tickets (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, title TEXT NOT NULL)');
const insert = db.prepare('INSERT INTO tickets (tenant_id, status, created_at, title) VALUES (?, ?, ?, ?)');
